// CPU-only validation for the runtime files generated by tools/mtp_rt.py.
// The CUDA drafter must never trust dense.txt offsets before allocating VRAM.
#pragma once

#include <algorithm>
#include <charconv>
#include <cstdint>
#include <istream>
#include <limits>
#include <set>
#include <sstream>
#include <string>
#include <vector>

namespace strata::core {

struct MtpDenseEntry {
    std::string name, kind;
    int64_t rows = 0, cols = 0;
    uint64_t off = 0, bytes = 0;
};

inline bool mtp_uint(const std::string& s, uint64_t& v) {
    if (s.empty()) return false;
    const auto* begin = s.data();
    const auto* end = begin + s.size();
    auto result = std::from_chars(begin, end, v);
    return result.ec == std::errc{} && result.ptr == end;
}

inline bool mtp_dense_index(std::istream& input, uint64_t file_bytes, std::vector<MtpDenseEntry>& out,
                            std::string& err) {
    out.clear();
    std::set<std::string> names;
    std::string line;
    size_t row = 0;
    while (std::getline(input, line)) {
        ++row;
        if (line.empty()) continue;
        if (out.size() >= 256 || line.size() > 1024) {
            err = "mtp: dense.txt has too many/overlong records";
            return false;
        }
        std::istringstream parser(line);
        std::string r, c, off, bytes, extra;
        MtpDenseEntry t;
        if (!(parser >> t.name >> t.kind >> r >> c >> off >> bytes) || (parser >> extra)) {
            err = "mtp: invalid dense.txt record at line " + std::to_string(row);
            return false;
        }
        if (t.name.size() > 200 || !names.insert(t.name).second) {
            err = "mtp: duplicate or invalid dense tensor name: " + t.name;
            return false;
        }
        uint64_t nr = 0, nc = 0;
        if (!mtp_uint(r, nr) || !mtp_uint(c, nc) || !mtp_uint(off, t.off) || !mtp_uint(bytes, t.bytes) ||
            nr == 0 || nc == 0 || nr > (uint64_t) (std::numeric_limits<int64_t>::max)() ||
            nc > (uint64_t) (std::numeric_limits<int64_t>::max)() || t.bytes == 0 ||
            nr > (std::numeric_limits<uint64_t>::max)() / nc) {
            err = "mtp: invalid dense tensor dimensions/offset/size: " + t.name;
            return false;
        }
        t.rows = (int64_t) nr;
        t.cols = (int64_t) nc;
        const uint64_t elems = nr * nc;
        uint64_t expected = 0;
        if (t.kind == "q8_0") {
            if (nc % 32 || elems / 32 > (std::numeric_limits<uint64_t>::max)() / 34) {
                err = "mtp: invalid Q8_0 row geometry: " + t.name;
                return false;
            }
            expected = elems / 32 * 34;
        } else if (t.kind == "bf16" || t.kind == "f32") {
            const uint64_t width = t.kind == "bf16" ? 2 : 4;
            if (elems > (std::numeric_limits<uint64_t>::max)() / width) {
                err = "mtp: tensor size overflow: " + t.name;
                return false;
            }
            expected = elems * width;
        } else {
            err = "mtp: unsupported dense tensor type " + t.kind + " for " + t.name;
            return false;
        }
        if (expected != t.bytes || t.off % 256 != 0 || t.off > file_bytes ||
            t.bytes > file_bytes - t.off) {
            err = "mtp: out-of-bounds, misaligned or incorrect tensor payload: " + t.name;
            return false;
        }
        out.push_back(std::move(t));
    }
    if (input.bad() || out.empty()) {
        err = "mtp: dense.txt is empty or unreadable";
        return false;
    }
    std::vector<const MtpDenseEntry*> order;
    for (const auto& t : out) order.push_back(&t);
    std::sort(order.begin(), order.end(), [](auto* a, auto* b) { return a->off < b->off; });
    for (size_t i = 1; i < order.size(); ++i) {
        if (order[i]->off < order[i - 1]->off + order[i - 1]->bytes) {
            err = "mtp: overlapping dense tensors: " + order[i - 1]->name + " and " + order[i]->name;
            return false;
        }
    }
    static constexpr const char* required[] = {
        "fc_embedding.weight", "fc_hidden.weight", "self_attn.q_proj.weight", "self_attn.k_proj.weight",
        "self_attn.v_proj.weight", "self_attn.o_proj.weight", "mlp.shared_expert.gate_proj.weight",
        "mlp.shared_expert.up_proj.weight", "mlp.shared_expert.down_proj.weight"
    };
    for (const char* name : required) {
        const auto it = std::find_if(out.begin(), out.end(), [name](const MtpDenseEntry& t) {
            return t.name == name && t.kind == "q8_0";
        });
        if (it == out.end()) {
            err = std::string("mtp: required Q8_0 dense projection missing: ") + name;
            return false;
        }
    }
    return true;
}

} // namespace strata::core
